using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.IO;

public class ForceFixIcons
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        string basePath = "Assets/Herbal/";

        // 1. Force Clean Backgrounds again with better logic
        string[] paths = Directory.GetFiles("Assets/Herbal", "*.png", SearchOption.AllDirectories);
        foreach(var path in paths)
        {
            string p = path.Replace("\\", "/");
            byte[] data = File.ReadAllBytes(p);
            Texture2D tex = new Texture2D(2,2);
            tex.LoadImage(data);
            Color[] pixels = tex.GetPixels();
            int w = tex.width;
            int h = tex.height;

            bool[] visited = new bool[w * h];
            Queue<int> q = new Queue<int>();

            for(int x=0; x<w; x++) { q.Enqueue(x); visited[x] = true; q.Enqueue((h-1)*w + x); visited[(h-1)*w + x] = true; }
            for(int y=0; y<h; y++) { q.Enqueue(y*w); visited[y*w] = true; q.Enqueue(y*w + w - 1); visited[y*w + w - 1] = true; }

            int clearedCount = 0;
            while(q.Count > 0)
            {
                int idx = q.Dequeue();
                Color c = pixels[idx];

                float maxRGB = Mathf.Max(c.r, Mathf.Max(c.g, c.b));
                float minRGB = Mathf.Min(c.r, Mathf.Min(c.g, c.b));
                float saturation = (maxRGB == 0) ? 0 : (maxRGB - minRGB) / maxRGB;

                // Allow ANY low saturation, light color (including pure white)
                bool isBg = (saturation < 0.35f && maxRGB > 0.4f) || (c.r > 0.85f && c.g > 0.85f && c.b > 0.85f);
                if (isBg)
                {
                    pixels[idx] = new Color(c.r, c.g, c.b, 0f);
                    clearedCount++;

                    int x = idx % w;
                    int y = idx / w;

                    int[] dx = {-1, 1, 0, 0};
                    int[] dy = {0, 0, -1, 1};
                    for(int i=0; i<4; i++)
                    {
                        int nx = x + dx[i];
                        int ny = y + dy[i];
                        if (nx >= 0 && nx < w && ny >= 0 && ny < h)
                        {
                            int nidx = ny * w + nx;
                            if (!visited[nidx] && pixels[nidx].a > 0.5f)
                            {
                                visited[nidx] = true;
                                q.Enqueue(nidx);
                            }
                        }
                    }
                }
            }
            if (clearedCount > 0)
            {
                tex.SetPixels(pixels);
                tex.Apply();
                File.WriteAllBytes(p, tex.EncodeToPNG());
                sb.AppendLine("[BG CLEARED] " + clearedCount + " pixels in " + p);
            }
        }

        AssetDatabase.Refresh();

        // Set texture settings
        foreach(var path in paths)
        {
            string p = path.Replace("\\", "/");
            TextureImporter ti = AssetImporter.GetAtPath(p) as TextureImporter;
            if (ti != null)
            {
                ti.textureType = TextureImporterType.Sprite;
                ti.spriteImportMode = SpriteImportMode.Single;
                ti.alphaIsTransparency = true;
                ti.SaveAndReimport();
            }
        }

        // 2. Assign Icons properly
        void AssignRecipeIcon(string recipeName, string iconName)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(basePath + "Recipes/" + recipeName + ".asset");
            var icon = AssetDatabase.LoadAssetAtPath<Sprite>(basePath + iconName + ".png");
            if (recipe != null && icon != null)
            {
                recipe.recipeImage = icon;
                EditorUtility.SetDirty(recipe);
                sb.AppendLine("[OK] Assigned Recipe Image for " + recipeName);
            }
            else
            {
                sb.AppendLine("[ERROR] Missing recipe or icon for " + recipeName + " -> " + iconName);
            }
        }

        AssignRecipeIcon("Jamu Pegal Linu", "PegalLinuIcon");
        AssignRecipeIcon("Jamu Penyegar", "PenyegarIcon");
        AssignRecipeIcon("Wedang Herbal", "WedangHerbalIcon");
        AssignRecipeIcon("Ramuan Penurun Panas", "PenurunPanasIcon");
        AssignRecipeIcon("Jamu Stamina", "StaminaIcon");
        AssignRecipeIcon("Ramuan Anti Mual", "AntiMualIcon");
        AssignRecipeIcon("Ramuan Pernapasan", "PernapasanIcon");
        AssignRecipeIcon("Jamu Sehat Desa", "SehatDesaIcon");

        // Fallbacks for old recipes
        AssignRecipeIcon("Jamu Beras Kencur", "JamuIcon");
        AssignRecipeIcon("Jamu Jahe", "DrinkIcon");
        AssignRecipeIcon("Jamu Kencur", "DrinkIcon");
        AssignRecipeIcon("Jamu Kunyit", "DrinkIcon");
        AssignRecipeIcon("Jamu Temulawak", "DrinkIcon");
        AssignRecipeIcon("Wedang Jahe", "DrinkIcon");

        AssetDatabase.SaveAssets();
        sb.AppendLine("DONE");
        return sb.ToString();
    }
}
